#!/usr/bin/env bash
# Public EpiATLAS gene quantification and per-sample RNA QC for 13 CLL samples.
# Usage: bash download_rna_cll13.sh [output_directory]
set -euo pipefail
rna_outdir="${1:-bcells_rna_cll13}"
mkdir -p "$rna_outdir"
while IFS=$'\t' read -r sample gene_url stats_url; do
    printf 'Downloading %s\n' "$sample"
    wget --continue --timeout=60 --tries=5 -O "$rna_outdir/$sample.genes.results" "$gene_url"
    wget --continue --timeout=60 --tries=5 -O "$rna_outdir/$sample.stats.json" "$stats_url"
done <<'RNA_MANIFEST'
